namespace ghidra.pcode.emu.jit.analysis;

using ghidra.pcode.emu.jit.op;
using ghidra.pcode.emu.jit.var;
using ghidra.pcode.emu.jit.var;

/**
 * A visitor that traverses the use-def graph upward, that is from uses toward definitions
 */
public interface JitOpUpwardVisitor : JitOpVisitor {
	/* @Override */
	void visitUnOp(JitUnOp op) {
		visitVal(op.u());
	}

	/* @Override */
	void visitBinOp(JitBinOp op) {
		visitVal(op.l());
		visitVal(op.r());
	}

	/* @Override */
	void visitStoreOp(JitStoreOp op) {
		visitVal(op.offset());
		visitVal(op.value());
	}

	/* @Override */
	void visitLoadOp(JitLoadOp op) {
		visitVal(op.offset());
	}

	/* @Override */
	void visitCallOtherOp(JitCallOtherOp otherOp) {
		foreach (JitVal v in otherOp.args()) {
			visitVal(v);
		}
	}

	/* @Override */
	void visitCallOtherDefOp(JitCallOtherDefOp otherOp) {
		foreach (JitVal v in otherOp.args()) {
			visitVal(v);
		}
	}

	/* @Override */
	void visitCatenateOp(JitCatenateOp op) {
		foreach (JitVal p in op.parts()) {
			visitVal(p);
		}
	}

	/* @Override */
	void visitPhiOp(JitPhiOp op) {
		foreach (JitVal opt in op.options().values()) {
			visitVal(opt);
		}
	}

	/* @Override */
	void visitSubPieceOp(JitSynthSubPieceOp op) {
		visitVal(op.v());
	}

	/* @Override */
	void visitCBranchOp(JitCBranchOp op) {
		visitVal(op.cond());
	}

	/* @Override */
	void visitBranchIndOp(JitBranchIndOp op) {
		visitVal(op.target());
	}

	/* @Override */
	void visitOutVar(JitOutVar v) {
		visitOp(v.definition());
	}
}
